3	import { pick } from "lodash-es";
4	import type * as Plotly from "plotly.js";
5	import { Arrays } from "@/utils/arrays";
6	import { createParser, type PlotlyTemplateParser } from "./parse-from-template";
7	
8	type AxisName = string;
9	type AxisDatum = unknown;
10	
11	export interface PlotlyClickSelection {
12	  points: Record<AxisName, AxisDatum>[] | Plotly.PlotDatum[];
13	  indices: number[];
14	  range: undefined;
15	  selections: unknown[];
16	}
17	
18	const CLICK_SELECTABLE_TRACE_TYPES = new Set(["heatmap", "histogram"]);
19	
20	const STANDARD_POINT_KEYS: string[] = [
21	  "x",
22	  "y",
23	  "z",
24	  "lat",
25	  "lon",
26	  "curveNumber",
27	  "pointNumber",
28	  "pointNumbers",
29	  "pointIndex",
30	] as const;
31	
32	function getPointIndex(point: Plotly.PlotDatum): number | undefined {
33	  if (typeof point.pointIndex === "number") {
34	    return point.pointIndex;
35	  }
36	
37	  if (typeof point.pointNumber === "number") {
38	    return point.pointNumber;
39	  }
40	
41	  return undefined;
42	}
43	
44	function isClickSelectablePoint(point: Plotly.PlotDatum): boolean {
45	  const traceType = point.data?.type;
46	  return typeof traceType === "string"
47	    ? CLICK_SELECTABLE_TRACE_TYPES.has(traceType)
48	    : false;
49	}
50	
51	export function extractIndices(points: Plotly.PlotDatum[]): number[] {
52	  return points.flatMap((point) => {
53	    const index = getPointIndex(point);
54	    return typeof index === "number" ? [index] : [];
55	  });
56	}
57	
58	/**
59	 * This is a hack to extract the points with their original keys,
60	 * instead of the ones that Plotly uses internally,
61	 * by using the hovertemplate.
62	 */
63	export function extractPoints(
64	  points: Plotly.PlotDatum[],
65	): Record<AxisName, AxisDatum>[] {
66	  if (!points) {
67	    return [];
68	  }
69	
70	  let parser: PlotlyTemplateParser | undefined;
71	
72	  return points.map((point) => {
73	    const standardPointFields = pick(point, STANDARD_POINT_KEYS);
74	
75	    // Get the first hovertemplate
76	    const hovertemplate = Array.isArray(point.data.hovertemplate)
77	      ? point.data.hovertemplate[0]
78	      : point.data.hovertemplate;
79	
80	    // For chart types with standard point keys (e.g. heatmaps),
81	    // or when there's no hovertemplate, pick keys directly from the point.
82	    if (!hovertemplate || point.data?.type === "heatmap") {
83	      return standardPointFields;
84	    }
85	
86	    // Update or create a parser
87	    parser = parser
88	      ? parser.update(hovertemplate)
89	      : createParser(hovertemplate);
90	    return {
91	      ...standardPointFields,
92	      ...parser.parse(point),
93	    };
94	  });
95	}
96	
97	export function extractClickSelection(
98	  evt: Readonly<Plotly.PlotMouseEvent>,
99	): PlotlyClickSelection | undefined {
100	  if (!evt.points?.length) {
101	    return undefined;
102	  }
103	
104	  const points = evt.points.filter(isClickSelectablePoint);
105	  if (points.length === 0) {
106	    return undefined;
107	  }
108	
109	  return {
110	    selections: Arrays.EMPTY,
111	    points: extractPoints(points),
112	    indices: extractIndices(points),
113	    range: undefined,
114	  };
115	}
