28	  // Match any characters except = for the key (non-greedy to avoid capturing previous content)
29	  const regex = /([^<=>]+)=%{([^}]+)}/g;
30	
31	  // Create an object to hold the key-selector pairs
32	  const keySelectorPairs: Record<string, string> = {};
33	
34	  let match: RegExpExecArray | null;
35	
36	  // Use exec to find all occurrences of the pattern and iterate over them
37	  while ((match = regex.exec(hovertemplate)) !== null) {
38	    // match[1] is the key, match[2] is the selector
39	    keySelectorPairs[match[1]] = match[2];
